#!/usr/bin/env python3
import argparse
import os
import sys


def read_as_text(path):
    with open(path, 'r', encoding='utf-8') as file:
        return file.read()


def count_text(text):
    lines = len(text.splitlines())
    words = len(text.split())
    characters = len(text)
    return lines, words, characters


def format_table(rows):
    if not rows:
        return ''
    headers = ('File', 'Lines', 'Words', 'Characters')
    widths = []
    for index, header in enumerate(headers):
        width = len(header)
        for row in rows:
            width = max(width, len(str(row[index])))
        widths.append(width)
    dash = '-'
    output = [
        f'{headers[0]:<{widths[0]}}  {headers[1]:>{widths[1]}}  {headers[2]:>{widths[2]}}  {headers[3]:>{widths[3]}}',
        f'{dash * widths[0]}  {dash * widths[1]}  {dash * widths[2]}  {dash * widths[3]}',
    ]
    for row in rows:
        output.append(
            f'{row[0]:<{widths[0]}}  {row[1]:>{widths[1]}}  {row[2]:>{widths[2]}}  {row[3]:>{widths[3]}}'
        )
    return chr(10).join(output)


def main():
    parser = argparse.ArgumentParser(
        prog='wordcount',
        description='Print line, word, and character counts for each file.'
    )
    parser.add_argument('file_paths', nargs='+', help='One or more file paths.')
    args = parser.parse_args()

    rows = []
    has_error = False

    for path in args.file_paths:
        if not os.path.exists(path):
            has_error = True
            print(f'wordcount: {path}: No such file or directory', file=sys.stderr)
            continue

        if not os.path.isfile(path):
            has_error = True
            print(f'wordcount: {path}: Is a directory or not a regular file', file=sys.stderr)
            continue

        try:
            text = read_as_text(path)
        except UnicodeDecodeError:
            has_error = True
            print(f'wordcount: {path}: File is not valid UTF-8 text', file=sys.stderr)
            continue
        except OSError as exc:
            has_error = True
            message = getattr(exc, 'strerror', None) or str(exc)
            print(f'wordcount: {path}: {message}', file=sys.stderr)
            continue

        line_count, word_count, character_count = count_text(text)
        rows.append((path, line_count, word_count, character_count))

    if rows:
        print(format_table(rows))

    return 1 if has_error else 0


if __name__ == '__main__':
    sys.exit(main())
